/**
 * Content model v2 (docs/04 §4, docs/10). A tool's content is keyed by its URL; category, subcategory, primary and
 * secondary keywords come from its registry row in content/keyword-map.json (generated by clustering), so keyword
 * ownership has one source of truth. Validated with zod at build: a bad content file fails the build.
 */
import { z } from 'zod';
import { wordCount } from '@/lib/format';

const isoDate = z.string().regex(/^\d{4}-\d{2}-\d{2}$/, 'YYYY-MM-DD');
export const toolUrl = z.string().regex(/^\/[a-z-]+\/[a-z0-9-]+\/$/, '/category/slug/');
// SEC-CODE-04: content URLs are https only. No javascript:, data:, http:.
export const httpsUrl = z.string().url().refine((u) => new URL(u).protocol === 'https:', 'https URLs only');

export const SourceSchema = z.object({
  title: z.string().min(5),
  url: httpsUrl,
  publisher: z.string().min(2),
  accessed: isoDate,
});

export const FaqSchema = z.object({
  q: z.string().min(10).max(160),
  a: z.string().min(40).max(900), // plain text; also used verbatim in FAQPage JSON-LD
});

export const ToolSchema = z.object({
  url: toolUrl,
  /** Engine spec id (lib/calculators/<id>.spec.ts). */
  calculator: z.string(),
  name: z.string().min(3),
  title: z.string().min(20).max(60),
  description: z.string().min(70).max(155),
  h1: z.string().min(3).max(70),
  directAnswer: z.string().refine((s) => wordCount(s) >= 40 && wordCount(s) <= 60, 'directAnswer must be 40–60 words'),
  appCategory: z.enum(['UtilitiesApplication', 'BusinessApplication', 'LifestyleApplication', 'EducationalApplication']).default('UtilitiesApplication'),
  whatItMeans: z.string().min(80),
  howToUse: z.array(z.string().min(10)).min(3).max(5),
  faqs: z.array(FaqSchema).min(5).max(8),
  // Release builds need ≥ 2 sources and an empty pendingVerification (tests/content.test.ts, release mode).
  sources: z.array(SourceSchema),
  pendingVerification: z.array(z.string()),
  /** Explicit related tools (URLs), may cross categories. Siblings in the same subcategory are added automatically. */
  related: z.array(toolUrl).max(6),
  disclaimer: z.string().optional(),
  published: isoDate,
  updated: isoDate,
  reviewed: z.object({ by: z.string(), credential: z.string().min(2), date: isoDate }).optional(), // only if real (playbook §10)
  /** Publishing batch: 1 = launch batch A, 2 = batch B (docs/07). */
  batch: z.union([z.literal(1), z.literal(2)]),
});

export type Tool = z.infer<typeof ToolSchema>;
export type ToolInput = z.input<typeof ToolSchema>;
export type Source = z.infer<typeof SourceSchema>;
export type Faq = z.infer<typeof FaqSchema>;
